# Validate that all characters in cleaned sequences are valid amino acid codes
valid_aa = set('ACDEFGHIKLMNPQRSTVWY')

def validate_fasta(filepath):
    with open(filepath) as f:
        for i, line in enumerate(f, 1):
            line = line.strip()
            if line.startswith('>'):
                continue  # Skip headers
            for char in line:
                if char not in valid_aa:
                    print(f"{filepath}:{i}: Invalid char '{char}' in line")
                    return False
    print(f"{filepath}: All sequences valid!")
    return True

validate_fasta('/app/environment/data/clean_train.fasta')
validate_fasta('/app/environment/data/clean_test.fasta')
